olid #ded3ef33;padding-top:8px}.catalog-page .actions{display:flex;flex-wrap:wrap;gap:8px;margin:20px 0}.catalog-page .button,.catalog-page button{border:1px solid var(--lilac);background:var(--cream);color:var(--plum);padding:10px 14px;border-radius:3px;font:inherit;text-decoration:none;cursor:pointer;min-height:44px}.catalog-page .secondary{background:#291e4599;color:var(--cream)}.catalog-page pre{background:#291e45d9;color:var(--cream);border:1px solid #ded3ef55;padding:20px;white-space:pre-wrap;overflow-wrap:anywhere;border-radius:3px}.catalog-page blockquote{border-left:2px solid var(--lilac);margin:16px 0;padding:8px 20px;max-width:730px}.catalog-detail{max-width:900px;background:#291e4599;padding:24px;margin-top:32px;border:1px solid #ded3ef33;border-radius:3px}.catalog-detail>h1{margin-top:8px}.catalog-detail>.eyebrow{margin-top:0}.catalog-page footer{border-top:1px solid #ded3ef44;margin-top:40px;padding-top:20px;font-size:12px;color:var(--lilac)}
